        return []

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Function to check if a position is valid
    def is_valid(r: int, c: int) -> bool:
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Use depth-first search (DFS) to find a path
    visited = [[False] * cols for _ in range(rows)]
    path = []

    def dfs(r: int, c: int, current_path: List[Tuple[int, int]]) -> bool:
        if (r, c) == goal:
            current_path.append((r, c))
            return True

        visited[r][c] = True
        current_path.append((r, c))

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and not visited[nr][nc]:
                if dfs(nr, nc, current_path):
                    return True

        current_path.pop()
        visited[r][c] = False
        return False

    if dfs(start[0], start[1], path):
        return path
    else:
        return []

