    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bellman-Ford algorithm to find shortest path
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break  # No more updates, early exit

    return dist[t] if dist[t] != float('inf') else -1

